<script>
(function () {
  "use strict";
  const canvas = document.getElementById("scene");
  const ctx = canvas.getContext("2d", { alpha: false });
  const controls = {
    speed: document.getElementById("speed"),
    columns: document.getElementById("columns"),
    rows: document.getElementById("rows"),
    layers: document.getElementById("layers"),
    mass: document.getElementById("mass")
  };
  const values = {
    speed: document.getElementById("speedValue"),
    columns: document.getElementById("columnsValue"),
    rows: document.getElementById("rowsValue"),
    layers: document.getElementById("layersValue"),
    mass: document.getElementById("massValue")
  };
  const cfg = {
    brickW: 0.50, brickH: 0.24, gravity: 9.81, brickFriction: 0.72,
    brickRestitution: 0.18, carMass: 1250, carW: 4.2, carH: 1.45,
    groundFriction: 0.85, nominalScale: 80, wallX: 13.4,
    fixedDt: 1 / 120
  };
  let settings = readSettings();
  let bodies = [];
  let joints = [];
  let car = null;
  let particles = [];
  let state = "ready";
  let elapsed = 0;
  let accumulator = 0;
  let lastFrame = 0;
  let cameraX = 0;
  let cameraScale = 50;
  let groundYpx = 0;
  let dpr = 1;
  let width = 0;
  let height = 0;
  let sceneRight = 21;
  let impactFlash = 0;
  let shake = 0;
  let settleClock = 0;
  let quietClock = 0;
  let impactSeen = false;
  let seed = 123456789;
  let sceneLeft = 0;
  let currentImpactForce = 0;
  let lastParticleTime = -10;

  function readSettings() {
    return {
      speed: Number(controls.speed.value),
      columns: Number(controls.columns.value),

      columns: Number(controls.columns.value),
      rows: Number(controls.rows.value),
      layers: Number(controls.layers.value),
      mass: Number(controls.mass.value)
    };
  }
  function updateValueLabels() {
    const format = { speed: [String(settings.speed), "m/s"], columns: [String(settings.columns), "bricks"], rows: [String(settings.rows), "bricks"], layers: [String(settings.layers), "layers"], mass: [settings.mass.toFixed(1), "kg"] };
    Object.keys(controls).forEach(function (key) {
      values[key].innerHTML = format[key][0] + "<small>" + format[key][1] + "</small>";
      const min = Number(controls[key].min), max = Number(controls[key].max);
      const pct = (Number(controls[key].value) - min) / (max - min) * 100;
      controls[key].style.setProperty("--fill", pct + "%");
    });
  }
  function bodyCreate(props) {
    const b = Object.assign({
      vx: 0, vy: 0, angle: 0, omega: 0, fx: 0, fy: 0,
      invMass: 0, invI: 0, kind: "brick", layer: 0, row: 0, col: 0,
      friction: cfg.brickFriction, restitution: cfg.brickRestitution,
      moving: false, shade: 0, color: "#a45039"
    }, props);
    b.mass = props.mass;
    b.invMass = 1 / b.mass;
    b.inertia = b.mass * (b.w * b.w + b.h * b.h) / 12;
    b.invI = 1 / b.inertia;
    b.c = Math.cos(b.angle);
    b.s = Math.sin(b.angle);
    return b;
  }
  function buildScene(launch) {
    settings = readSettings();
    bodies = [];
    joints = [];
    particles = [];
    elapsed = 0;
    accumulator = 0;
    settleClock = 0;
    quietClock = 0;
    impactSeen = false;
    impactFlash = 0;
    shake = 0;
    currentImpactForce = 0;
    lastParticleTime = -10;
    seed = 123456789;
    const netDriveAcceleration = 36 - cfg.groundFriction * cfg.gravity;
    const accelerationDistance = settings.speed * settings.speed / (2 * netDriveAcceleration);
    const runup = Math.max(9.1, accelerationDistance + 1.25);
    const startX = cfg.wallX - cfg.carW / 2 - runup;
    const carBody = bodyCreate({
      kind: "car", x: startX, y: cfg.carH / 2, w: cfg.carW, h: cfg.carH,
      mass: cfg.carMass, friction: cfg.groundFriction, restitution: 0.07,
      color: "#d98b3b", layer: -1
    });
