    bodies.push(carBody);
    const brickGrid = [];
    const palette = ["#a84e37", "#b0563d", "#9c4734", "#ad523a", "#a34a36", "#b45c41"];
    for (let layer = 0; layer < settings.layers; layer++) {
      brickGrid[layer] = [];
      for (let row = 0; row < settings.rows; row++) {
        brickGrid[layer][row] = [];
        const stagger = (row % 2) * cfg.brickW * 0.5;
        for (let col = 0; col < settings.columns; col++) {
          const x = cfg.wallX + col * cfg.brickW + cfg.brickW * 0.5 + cfg.brickW * 0.5 - stagger;
          const y = row * cfg.brickH + cfg.brickH * 0.5;
          const tone = (row * 5 + col * 3 + layer * 2) % palette.length;
          const brick = bodyCreate({
            kind: "brick", x: x, y: y, w: cfg.brickW, h: cfg.brickH,
            mass: settings.mass, layer: layer, row: row, col: col,
            friction: cfg.brickFriction, restitution: cfg.brickRestitution,
            color: palette[tone], shade: (col * 7 + row * 3 + layer * 5) % 9
          });
          brickGrid[layer][row][col] = brick;
          bodies.push(brick);
        }
      }
      for (let row = 0; row < settings.rows; row++) {
        for (let col = 0; col < settings.columns - 1; col++) {
          makeJoint(brickGrid[layer][row][col], brickGrid[layer][row][col + 1], "horizontal");
        }
      }
      for (let row = 0; row < settings.rows - 1; row++) {
        for (let col = 0; col < settings.columns; col++) {
          const lower = brickGrid[layer][row][col];
          const lowerLeft = lower.x - lower.w / 2;
          const lowerRight = lower.x + lower.w / 2;
          let bestUpper = null;
          let bestOverlap = 0;
          let anchorX = 0;
          for (let upperCol = 0; upperCol < settings.columns; upperCol++) {
            const upper = brickGrid[layer][row + 1][upperCol];
            const overlapLeft = Math.max(lowerLeft, upper.x - upper.w / 2);
            const overlapRight = Math.min(lowerRight, upper.x + upper.w / 2);
            const overlap = overlapRight - overlapLeft;
            if (overlap > bestOverlap) {
              bestOverlap = overlap;
              bestUpper = upper;
              anchorX = (overlapLeft + overlapRight) / 2;
            }
          }
          if (bestUpper && bestOverlap > 0.015) {
            const anchor = { x: anchorX, y: (lower.y + lower.h / 2 + bestUpper.y - bestUpper.h / 2) / 2 };
            makeJointAt(lower, bestUpper, anchor, "vertical");
          }
        }
      }
    }
    sceneRight = cfg.wallX + settings.columns * cfg.brickW + 0.75;
    sceneLeft = Math.min(0, startX - 2.5);
    cameraX = sceneLeft + 0.1;
    state = launch ? "running" : "ready";
    updateStateLabel();
    updateTelemetry();
    if (launch) {
      settleClock = 0;
      car.vx = 0;
    }
  }
  function makeJoint(a, b, type) {
    const point = type === "horizontal"
      ? { x: (a.x + a.w / 2 + b.x - b.w / 2) / 2, y: (a.y + b.y) / 2 }
      : { x: (a.x + b.x) / 2, y: (a.y + a.h / 2 + b.y - b.h / 2) / 2 };
    makeJointAt(a, b, point, type);
  }
  function makeJointAt(a, b, point, type) {
    const strength = 2100;
    joints.push({
      a: a, b: b, localA: toLocal(a, point), localB: toLocal(b, point),
      angle0: b.angle - a.angle, fx: 0, fy: 0, torque: 0,
      maxForce: strength, maxTorque: strength * 0.19, type: type, broken: false
    });
  }
  function toLocal(body, point) {
    const dx = point.x - body.x, dy = point.y - body.y;
    const c = body.c, s = body.s;
    return { x: dx * c + dy * s, y: -dx * s + dy * c };
  }
  function jointAnchor(body, local) {
    const c = body.c, s = body.s;
    return { x: body.x + local.x * c - local.y * s, y: body.y + local.x * s + local.y * c };
  }
  function worldVertices(body, dx, dy) {
    const hx = body.w / 2, hy = body.h / 2;
    const c = body.c, s = body.s;
    const coords = [[-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy]];
    return coords.map(function (p) { return { x: body.x + p[0] * c - p[1] * s + (dx || 0), y: body.y + p[0] * s + p[1] * c + (dy || 0) }; });
  }
  function axes(body) {
    const c = body.c, s = body.s;
    return [{ x: c, y: s }, { x: -s, y: c }];
